// Reads the SQL example sections of a rendered StackQL provider resource
// page, for template.js. Runs in the browser when the reader opens the menu;
// `doc` is the page's document. CommonJS, like template.js.
//
// The resource pages are generated by @stackql/provider-utils. Their section
// headings get these ids from Docusaurus:
//
//   ## `SELECT` examples  -> #select-examples
//   ## `INSERT` examples  -> #insert-examples (#insert-example on older pages)
//   ## `UPDATE` examples  -> #update-examples (#update-example)
//   ## `REPLACE` examples -> #replace-examples
//   ## `DELETE` examples  -> #delete-examples (#delete-example)
//   ## Lifecycle Methods  -> #lifecycle-methods
//
// A section's examples are tabs, one per method; the preferred tab is read
// first and the section's first code block otherwise.

/** The elements after `heading` up to the next <h2>. */
function elementsAfterHeading(heading) {
  const elements = [];
  let el = heading.nextElementSibling;
  while (el && el.tagName !== 'H2') {
    elements.push(el);
    el = el.nextElementSibling;
  }
  return elements;
}

/**
 * The text of a <code> element with its line breaks. prism-react-renderer
 * renders each line as a child element, and textContent joins them without
 * newlines, so the lines are joined here.
 */
function codeText(codeEl) {
  if (codeEl.children.length > 0) {
    return Array.from(codeEl.children)
      .map((line) => line.textContent.replace(/\n$/, ''))
      .join('\n');
  }
  return codeEl.textContent;
}

/**
 * The code of the tab labelled `preferredTab` (case-insensitive) within
 * `elements`, or with no preference (or no such tab) the first code block.
 */
function codeFromElements(elements, preferredTab) {
  if (preferredTab) {
    const wanted = preferredTab.toLowerCase();
    for (const el of elements) {
      const tabs = el.querySelectorAll('[role="tab"]');
      const panels = el.querySelectorAll('[role="tabpanel"]');
      for (let i = 0; i < tabs.length; i++) {
        if (tabs[i].textContent.trim().toLowerCase() === wanted && panels[i]) {
          const codeEl = panels[i].querySelector('pre code');
          if (codeEl) return codeText(codeEl);
        }
      }
    }
    return null;
  }
  for (const el of elements) {
    const codeEl = el.querySelector('pre code');
    if (codeEl) return codeText(codeEl);
  }
  return null;
}

function section(doc, ids) {
  for (const id of ids) {
    const heading = doc.getElementById(id);
    if (heading) return elementsAfterHeading(heading);
  }
  return null;
}

/** The first code found by trying each tab label in turn, then any code. */
function firstCode(elements, preferredTabs = []) {
  for (const tab of preferredTabs) {
    const code = codeFromElements(elements, tab);
    if (code) return code;
  }
  return codeFromElements(elements);
}

/** The example sections of the page, as buildTemplate() takes them. */
function extractSections(doc) {
  const sections = {};

  // SELECT: the single-resource read ("get") is the existence check.
  const select = section(doc, ['select-examples']);
  if (select) sections.select = firstCode(select, ['get (all properties)', 'get']);

  // INSERT: the full create, not the "Manifest" (YAML) tab.
  const insert = section(doc, ['insert-examples', 'insert-example']);
  if (insert) sections.insert = firstCode(insert, ['All Properties', 'create']);

  const update = section(doc, ['update-examples', 'update-example']);
  if (update) sections.update = firstCode(update);

  const replace = section(doc, ['replace-examples']);
  if (replace) sections.replace = firstCode(replace);

  const del = section(doc, ['delete-examples', 'delete-example']);
  if (del) sections.delete = firstCode(del);

  // Without a DELETE section, the "delete" tab of the lifecycle methods.
  if (!sections.delete) {
    const lifecycle = section(doc, ['lifecycle-methods']);
    if (lifecycle) sections.delete = codeFromElements(lifecycle, 'delete');
  }

  return sections;
}

module.exports = { extractSections, codeFromElements, codeText, elementsAfterHeading };
